const productData = $('Webhook — Produit candidat reçu').first().json;
const googleResults = $('Google Shopping — Prix concurrents').first().json?.shopping_results || [];
const amazonResults = $('Amazon — Prix & rang bestseller').first().json?.search_results || [];
const metaAds = $('Meta Ads Library — Pubs actives').first().json?.data || [];

const supplierCost = productData.price_supplier || 0;

// Extraire les prix concurrents
const allPrices = [
  ...googleResults.map(r => parseFloat(r.price?.replace(/[^0-9.]/g, '') || 0)).filter(p => p > 0),
  ...amazonResults.map(r => parseFloat(r.price?.value || 0)).filter(p => p > 0)
];

const priceMin = allPrices.length ? Math.min(...allPrices) : supplierCost * 2;
const priceMax = allPrices.length ? Math.max(...allPrices) : supplierCost * 5;
const priceMed = allPrices.length ? allPrices.sort((a,b)=>a-b)[Math.floor(allPrices.length/2)] : supplierCost * 3;

// Saturation via Meta Ads (nbr de pubs actives > 30j)
const adsOver30Days = metaAds.filter(ad => {
  const start = new Date(ad.ad_delivery_start_time);
  const diffDays = (Date.now() - start) / (1000 * 60 * 60 * 24);
  return diffDays > 30;
}).length;

const saturationLevel = adsOver30Days > 20 ? 'SATURE' : adsOver30Days > 8 ? 'CONCURRENTIEL' : 'VIERGE';

// Multiplicateur dynamique
const multiplierMap = { VIERGE: 4.2, CONCURRENTIEL: 2.6, SATURE: 0 };
const multiplier = multiplierMap[saturationLevel];

if (saturationLevel === 'SATURE') {
  return [{ json: { ...productData, verdict_pricing: 'REJETE', raison: 'Marché saturé (>20 pubs actives)', saturation_level: saturationLevel } }];
}

const targetPriceCHF = Math.round(supplierCost * multiplier * 10) / 10;
// CPA estimé (benchmark Meta pour e-commerce FR/CH)
const estimatedCPA = saturationLevel === 'VIERGE' ? targetPriceCHF * 0.20 : targetPriceCHF * 0.28;
const shippingCost = 3.5;
const netMargin = targetPriceCHF - supplierCost - estimatedCPA - shippingCost;
const netMarginPct = (netMargin / targetPriceCHF) * 100;

const verdictPricing = netMarginPct >= 30 ? 'VALIDE' : 'REJETE';

return [{
  json: {
    ...productData,
    pricing: {
      supplier_cost: supplierCost,
      price_min_market: priceMin,
      price_max_market: priceMax,
      price_median_market: priceMed,
      target_price_chf: targetPriceCHF,
      crossed_price_chf: Math.round(priceMed * 1.15 * 10) / 10,
      multiplier,
      estimated_cpa: estimatedCPA,
      net_margin_chf: netMargin,
      net_margin_pct: Math.round(netMarginPct * 10) / 10,
      saturation_level: saturationLevel,
      active_ads_30d: adsOver30Days
    },
    verdict_pricing: verdictPricing,
    raison_pricing: verdictPricing === 'VALIDE'
      ? `Marge nette ${Math.round(netMarginPct)}% — marché ${saturationLevel}`
      : `Marge insuffisante (${Math.round(netMarginPct)}% < 30%)`
  }
}];
